 let mut t=String::from("# Bounded G2 prefix-tree SDK route on C7a\n\n");writeln!(t,"The declared whole-SDK gate **{}**. No candidate is adopted; production remains unchanged. This tests whether the [positive high-core component result](../2026-10-26-g2-tree-c7a/README.md) improves complete verified proofs, including comparison against the accepted32-worker primary configuration.\n",if a["target_adoption_gate_passed"]==true{"passes"}else{"fails"}).unwrap();
