 t.push_str("\n## Validation and profiles\n\n117unfiltered native core tests,raw2/cubic6andgeneratedIFMA checks pass. Tests cover complete-curve signed/odd/skewed bucket cases,independent generator sums including30089points,checked cost overflow,route boundaries,denial without scalar mutation and successful64-worker route charge release. Portablex86-64andnative-noIFMA core/prover/zolana consumer compilation passes. Field math is unchanged; the33-test target qualification is inherited. Compilation is not phone performance evidence.\n\nExact-container preflight covers allnine shapes and fourengines at4workers,OFF/ON for1x2/2x2at64workers,and one primaryON64with explicit optional-budget ceiling0. The64-worker local checks oversubscribe this32logical-CPU host and are correctness-only. All41exports independently verify; route traces confirm selection only on eligible ON64cases and fallback elsewhere. This budget check does not establish an arbitrary minimum RAM or giant-circuit memory-pressure guarantee.\n\nCombined7580SDK requests produce373distinct Gnark-verified exports/746proof-public members. Every export verifies again locally after transport across9pinned keys. Reverification is counted once. Fixture public hashes,164-byte length and freshness against5958prior identities pass; the new prior set is6331. All source/image/input/executable hashes and route receipts are retained.\n\nEight primary32/96profiles,one perengine/count,follow all latencies. Each has51timed calls after3primes,cycles:u at199Hz,gated after preparation through direct pinned perf with --no-buildid-cache. Categories may contain inlined arithmetic and are not exclusive-stage wall time. Raw profiles stay local with hashes; decoded reports are archived.\n\n|Profile|Samples|Lost|Epoch+scheduler %|Grouping %|Tree %|\n|---|---:|---:|---:|---:|---:|\n");for(name,p)in a["profiles"].as_object().unwrap(){let c=&p["category_percent"];writeln!(t,"|{name}|{}|{}|{:.3}|{:.3}|{:.3}|",p["samples"],p["lost_records"],c["epoch"].as_f64().unwrap_or(0.)+c["scheduler"].as_f64().unwrap_or(0.),c["grouping"].as_f64().unwrap_or(0.),c["g2_tree"].as_f64().unwrap_or(0.)).unwrap();}
 t.push_str("\nTopology/CPU flags and cgroup CPU,memory,swap snapshots are retained before workflow,after all latency and after profiles. The after-latency snapshot is written by the first profile adapter before SDK preparation and before the disabled profiler is enabled. Stage counters include complete processes and verification; they are not per-query measures. No concurrent-throughput,phone,TEE,giant or swap qualification is claimed.\n\n## Cleanup and artifacts\n\nThe owned instance is terminated; its EBS volume,temporary ECR tag,private S3object/bucket are absent,and the presigned parameter file is deleted. No live temporary benchmark instance remains in the region. Production source,networking and IAM remain unchanged.\n\n[Design](artifacts/design.md),[implementation audit](artifacts/implementation-audit.json),[full analysis](artifacts/analysis.json),[all request/profile rows](artifacts/remote-results/output/measure/performance/rows.json),[route checks](artifacts/local-output/preflight/route-analysis.json),[proof inventory](artifacts/proof-inventory.json),[posttransport Gnark log](artifacts/post-transport-gnark.log),[cleanup](artifacts/cleanup-complete.json),and[artifact index](artifacts/artifact-index.json) retain the evidence. Keys,executables and raw profiles remain local with hashes. Secret transport files are excluded.\n");
 fs::create_dir_all(D).unwrap();fs::write(Path::new(D).join("README.md"),t).unwrap();let close=json!({"status":"complete SDK experiment; no adoption","root":R,"report":format!("{D}/README.md"),"sdk_requests":7580,"distinct_gnark_exports":373,"proof_public_members":746,"next_prior_proof_count":6331,"native_core_tests":117,"raw_tests":2,"cubic_tests":6,"portable_and_no_ifma_consumer_checks":true,"target_adoption_gate_passed":a["target_adoption_gate_passed"],"primary_ON64_accepted32":a["primary_ON64_accepted32"],"cleanup":cleanup,"adopted":false,"goal_achieved":false,"CPU10x_rows":reached});save(r.join("closeout.json"),&close);
 let dest=Path::new(D).join("artifacts");fs::create_dir_all(&dest).unwrap();let mut files=Vec::new();for d in ["candidate","native","local-output","remote-results","context","final-context"]{walk(&r.join(d),&mut files);}for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}let mut index=BTreeMap::new();let mut raw=BTreeMap::new();for p in files{let rel=p.strip_prefix(r).unwrap();let name=p.file_name().unwrap().to_str().unwrap();if name.contains(".secret"){continue;}if name=="perf.data"{raw.insert(rel.display().to_string(),json!({"sha256":hash(&p),"bytes":fs::metadata(&p).unwrap().len()}));continue;}let ext=p.extension().and_then(|s|s.to_str()).unwrap_or("");if !rel.starts_with("candidate")&&!matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"proof"|"public"|"stderr"|"stdout"|"sh")&&name!="Dockerfile"&&name!="zopro-keys.lock"{continue;}let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();index.insert(rel.display().to_string(),hash(target));}for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}assert_eq!(raw.len(),8);save(dest.join("artifact-index.json"),&json!({"sha256":index,"raw_profiles_local_only":raw,"secrets_excluded":true}));state("G2 tree SDK closed; ready to commit/push",close);println!("Archived{}files;7580SDK373Gnark;noadoption",index.len());
